  Definition CSREGS : list reg := [23; 24]%bv.

  Lemma pm_copy_loop : forall (k : nat) (w : pmw MI ST) c0 K (fx : FPState) (I : ictxR) A M model c R (p pend ia : Z),
    PMS w c0 K -> frm_zero (@fp_csr fx) ->
    PMX w A M model c -> c_tr c = [] -> pm_bud (w_n w) c -> oregs w R -> loop_mem w M ->
    ictx w M (i_io I) (i_fw I) (i_iwc I) (i_op I) (i_d I) -> ifr w M ->
    getr R 24%bv = Z_to_bv 64 ia -> getr R 22%bv = Z_to_bv 64 (c_endian c) -> c_endian c < 2 ->
    getr R 10%bv = Z_to_bv 64 p -> getr R 23%bv = Z_to_bv 64 pend -> pend = p + 4 * Z.of_nat k -> (0 < k)%nat ->
    w_words w <> 0 -> w_words w <= p -> pend <= w_words w + 4 * w_n w -> p mod 4 = 0 ->
    Zlen (t3b (c_v2 c)) + Z.of_nat k <= 2 ^ 17 ->
    (forall A' M' model' R' (b2 cap2 : Z) (xs2 : list Z),
        PMX w A' M' model' (set_v2 c (b2, xs2, cap2)) -> pm_bud (w_n w) (set_v2 c (b2, xs2, cap2)) ->
        Zlen xs2 = Zlen (t3b (c_v2 c)) + Z.of_nat k ->
        oregs w R' -> getr R' 24%bv = Z_to_bv 64 ia -> loop_mem w M' ->
        ictx w M' (i_io I) (i_fw I) (i_iwc I) (i_op I) (i_d I) -> ifr w M' ->
        srealizes SEGS (cfg fx R' 0x68120 M' model') K) ->
